import type { MarketPriceRecord } from "../types";
import demoPrices from "./demo-prices.json";

/**
 * Regional price table. Currently DEMO data generated by
 * scripts/generate-demo-prices.mjs — replace with real data before launch.
 */
export const MARKET_DATA: MarketPriceRecord[] =
  demoPrices as unknown as MarketPriceRecord[];

/** True when any record is demo data (the UI must then say so, ТЗ P-07). */
export function isDemoData(data: MarketPriceRecord[] = MARKET_DATA): boolean {
  return data.some((r) => r.is_demo);
}
